import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
export async function installCollageProbe(page){await page.addInitScript(()=>{const Original=Worker;window.__collageProbe={started:0,stopped:0,hold:false,holdHash:false};const digest=crypto.subtle.digest.bind(crypto.subtle);crypto.subtle.digest=(...args)=>{if(!window.__collageProbe.holdHash)return digest(...args);return new Promise((resolve,reject)=>{window.__collageProbe.releaseHash=async()=>{window.__collageProbe.holdHash=false;try{resolve(await digest(...args));}catch(error){reject(error);}};});};window.Worker=class extends Original{constructor(url,options){super(url,options);this.collage=String(url).includes('collage-worker-');if(this.collage)window.__collageProbe.started++;}postMessage(data,...rest){if(this.collage&&window.__collageProbe.hold&&data.action==='open')return;super.postMessage(data,...rest);}terminate(){if(this.collage&&!this.done){this.done=true;window.__collageProbe.stopped++;}super.terminate();}};});}
export async function exerciseGalleryCollage(page,photos){
 await expect(page.locator('.photo-card').first()).toBeVisible();for(const photo of photos)await page.locator('.photo-card').filter({hasText:photo.file_name}).locator('.photo-image').click();
 await page.locator('.library-toolbar').getByRole('button',{name:'照片拼图',exact:true}).click();const dialog=page.getByRole('dialog',{name:'照片拼图'});await expect(dialog.getByRole('button',{name:'保存布局清单',exact:true})).toBeEnabled();await expect(dialog.locator('.collage-cells button')).toHaveCount(photos.length);
 const next=page.waitForEvent('download');await dialog.getByRole('button',{name:'保存布局清单',exact:true}).click();const saved=JSON.parse(readFileSync(await(await next).path(),'utf8'));expect(saved.sources.map(s=>s.photo_id).sort()).toEqual(photos.map(p=>p.id).sort());for(const photo of photos){const source=saved.sources.find(s=>s.photo_id===photo.id);expect(source.name).toBe(photo.file_name);expect(source.sha256).toBe(photo.file_hash);expect(source.profile).toEqual(photo.decode_profile||{version:2,extra_orientation:1});}
 await dialog.getByRole('button',{name:'关闭',exact:true}).click();await expect(dialog).toHaveCount(0);return saved;
}
export async function exerciseCollageUI(page,info,lang){
 const text=(zh,en)=>lang==='en'?en:zh,dialog=page.getByRole('dialog',{name:text('照片拼图','Photo collage')}),button=(zh,en)=>dialog.getByRole('button',{name:text(zh,en),exact:true}),field=(zh,en)=>dialog.getByLabel(text(zh,en),{exact:true});
 const bytes=await page.evaluate(async()=>{const result=[];for(let j=0;j<3;j++){const c=new OffscreenCanvas(320,200),x=c.getContext('2d'),g=x.createLinearGradient(0,0,320,200);g.addColorStop(0,['#154566','#cc6644','#337755'][j]);g.addColorStop(1,'#eeddaa');x.fillStyle=g;x.fillRect(0,0,320,200);x.fillStyle='#ffeecc';x.fillRect(20+j*30,50,35,60);result.push([...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())]);}return result;});
 const files=bytes.map((b,i)=>({name:`Collage-${i}.png`,mimeType:'image/png',buffer:Buffer.from(b)})),input=dialog.locator('input[type=file]').nth(0),replace=dialog.locator('input[type=file]').nth(1),project=dialog.locator('input[type=file]').nth(2);
 const ready=async()=>{await expect(button('导出拼图 PNG','Export collage PNG')).toBeEnabled();await expect(dialog.locator('.collage-stage img')).toHaveJSProperty('naturalWidth',600);await expect(dialog.locator('.collage-stage')).toHaveAttribute('aria-busy','false');};
 const download=async(zh,en)=>{const next=page.waitForEvent('download');await button(zh,en).click();const d=await next;return readFileSync(await d.path());};
 await input.setInputFiles(files.slice(0,2));await expect(dialog.locator('.collage-templates button')).toHaveCount(6);await field('画布宽度','Canvas width').fill('600');await field('画布高度','Canvas height').fill('400');await field('画布高度','Canvas height').press('Tab');await ready();
 for(let i=0;i<6;i++){await dialog.locator('.collage-templates button').nth(i).click();await expect(dialog.locator('.collage-templates button').nth(i)).toHaveAttribute('aria-pressed','true');}
 await dialog.locator('.collage-templates button').nth(1).click();const layout=await dialog.locator('.collage-templates button').nth(1).getAttribute('aria-label');
 const first=dialog.getByRole('button',{name:text('拼图单元格 1','Collage cell 1'),exact:true});await dialog.evaluate(el=>el.scrollTop=0);const box=await first.boundingBox();await page.mouse.move(box.x+box.width/2,box.y+box.height/2);await page.mouse.down();await page.mouse.move(box.x+box.width/2+20,box.y+box.height/2+10,{steps:4});await page.mouse.up();const dragged=JSON.parse(await download('保存布局清单','Save layout document'));expect(dragged.cells[0].pan.x).toBeGreaterThan(0);expect(dragged.cells[0].pan.y).toBeGreaterThan(0);await button('撤销拼图','Undo collage').click();
 await field('格内缩放','Cell zoom').fill('1.4');await dialog.getByRole('button',{name:text('拼图单元格 1','Collage cell 1'),exact:true}).press('Shift+ArrowRight');await field('交换照片','Swap photos').selectOption('1');
 let document=JSON.parse(await download('保存布局清单','Save layout document'));expect(document.cells[1]).toMatchObject({zoom:1.4,pan:{x:.1,y:0}});expect(document.sources).toHaveLength(2);expect(document.sources.every(s=>/^[a-f0-9]{64}$/.test(s.sha256))).toBe(true);
 await button('撤销拼图','Undo collage').click();expect(JSON.parse(await download('保存布局清单','Save layout document')).cells[0].zoom).toBe(1.4);await button('重做拼图','Redo collage').click();
 await ready();const output=await download('导出拼图 PNG','Export collage PNG');document=JSON.parse(await download('保存布局清单','Save layout document'));
 await input.setInputFiles(Array.from({length:11},(_,i)=>({...files[0],name:i+'.png'})));await expect(dialog.getByRole('alert')).toBeVisible();expect(JSON.parse(await download('保存布局清单','Save layout document'))).toEqual(document);
 await replace.setInputFiles({name:'Broken.png',mimeType:'image/png',buffer:Buffer.from('not a photo')});await expect(dialog.getByRole('alert')).toBeVisible();expect(JSON.parse(await download('保存布局清单','Save layout document'))).toEqual(document);
 await project.setInputFiles({name:'Future.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify({...document,version:99}))});await expect(dialog.getByRole('alert')).toBeVisible();
 const reordered=JSON.stringify(document,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).reverse()):v);
 await project.setInputFiles({name:'Layout.json',mimeType:'application/json',buffer:Buffer.from(reordered)});await expect(button('选择清单中的原图','Choose document originals')).toBeVisible();await input.setInputFiles([files[2]]);await expect(dialog.getByRole('alert')).toBeVisible();await input.setInputFiles(files.slice(0,2).reverse());await ready();expect(await download('导出拼图 PNG','Export collage PNG')).toEqual(output);
 await replace.setInputFiles(files[2]);await ready();await expect(dialog.getByRole('button',{name:layout,exact:true})).toHaveAttribute('aria-pressed','true');const replaced=JSON.parse(await download('保存布局清单','Save layout document'));expect(replaced.sources.some(s=>s.name==='Collage-2.png')).toBe(true);expect(replaced.cells[1].zoom).toBe(1.4);
 await button('移除照片','Remove photo').click();await ready();await expect(dialog.locator('.collage-cells button')).toHaveCount(1);await expect(button('移除照片','Remove photo')).toBeDisabled();await input.setInputFiles([files[2]]);await ready();await expect(dialog.locator('.collage-cells button')).toHaveCount(2);
 // A partially uncovered cell is visibly diagnosed without becoming an export decoration.
 const oldPreview=await dialog.locator('.collage-stage img').getAttribute('src');await field('格内缩放','Cell zoom').fill('0.5');await expect(dialog.locator('.collage-stage img')).not.toHaveAttribute('src',oldPreview);await ready();await expect(dialog.getByRole('status').filter({hasText:text('斜线','guide stripes')})).toBeVisible();await dialog.evaluate(el=>el.scrollTop=0);await dialog.screenshot({path:info.outputPath('collage-'+lang+'.png')});
 if(lang==='en')expect(await dialog.innerText()).not.toMatch(/[\u3400-\u9fff]/);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);expect(await dialog.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true);
 page.once('dialog',d=>d.dismiss());await button('关闭','Close').click();await expect(dialog).toBeVisible();page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog).toHaveCount(0);expect(await page.evaluate(()=>window.__collageProbe.started-window.__collageProbe.stopped)).toBe(0);
 // Closing while the main thread hashes a manifest source must not start a new worker later.
 await page.locator('.studio-tool').filter({hasText:text('照片拼图','Photo collage')}).click();const single={...document,template:'1-full',sources:[document.sources[0]],cells:[{source_id:document.sources[0].id,zoom:1,pan:{x:0,y:0}}]};
 await project.setInputFiles({name:'Single.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(single))});const starts=await page.evaluate(()=>{window.__collageProbe.holdHash=true;return window.__collageProbe.started;});await input.setInputFiles([files[0]]);await page.waitForFunction(()=>typeof window.__collageProbe.releaseHash==='function');page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog).toHaveCount(0);await page.evaluate(async()=>{await window.__collageProbe.releaseHash();await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);});expect(await page.evaluate(()=>window.__collageProbe.started)).toBe(starts);
 // Closing an in-flight decode releases the candidate worker and never publishes a late scene.
 await page.locator('.studio-tool').filter({hasText:text('照片拼图','Photo collage')}).click();await page.evaluate(()=>window.__collageProbe.hold=true);await input.setInputFiles([files[0]]);await expect(button('添加照片 / RAW','Add photos / RAW')).toBeDisabled();page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog).toHaveCount(0);expect(await page.evaluate(()=>window.__collageProbe.started-window.__collageProbe.stopped)).toBe(0);
}
